function leerJsonEstricto(texto) {
  // JSON.parse comprueba gramatica; este recorrido adicional detecta claves
  // duplicadas incluso si usan escapes y numeros con precision no representable.
  const value = JSON.parse(texto);
  let pos = 0;
  function espacio() { while (/\s/.test(texto[pos] ?? '') && pos < texto.length) pos++; }
  function cadena() {
    const inicio = pos++;
    while (pos < texto.length) {
      if (texto[pos] === '\\') pos += 2;
      else if (texto[pos++] === '"') return JSON.parse(texto.slice(inicio, pos));
    }
    throw new Error('JSON_INVALIDO');
  }
  function valor() {
    espacio();
    if (texto[pos] === '{') {
      pos++; espacio(); const vistas = new Set();
      if (texto[pos] === '}') { pos++; return; }
      while (true) {
        espacio(); const key = cadena();
        if (vistas.has(key)) throw new Error('CLAVE_REPETIDA');
        vistas.add(key); espacio(); pos++; valor(); espacio();
        if (texto[pos++] === '}') return;
      }
    }
    if (texto[pos] === '[') {
      pos++; espacio();
      if (texto[pos] === ']') { pos++; return; }
      while (true) { valor(); espacio(); if (texto[pos++] === ']') return; }
    }
    if (texto[pos] === '"') { cadena(); return; }
    const inicio = pos;
    while (pos < texto.length && !/[\s,\]}]/.test(texto[pos])) pos++;
    const token = texto.slice(inicio, pos);
    if (/^-?\d/.test(token)) {
      const [mantisa, exponente = '0'] = token.toLowerCase().split('e');
      const decimales = (mantisa.split('.')[1] ?? '').replace(/0+$/, '').length;
      if (decimales - Number(exponente) > 4) throw new Error('PRECISION_NUMERICA');
    }
  }
  valor();
  return value;
}

function prepararIngestaSimulada(entrada, configuracion, recibidaEn) {
  const rechazo = codigo => ({ estado: 'rechazado', codigo, origen: 'simulado', persistido: false });
  if (configuracion?.acl_verificada !== true || configuracion?.retencion_broker_desactivada !== true) return rechazo('CANAL_LOCAL_NO_VERIFICADO');
  if (typeof recibidaEn !== 'string' || !Number.isFinite(Date.parse(recibidaEn)) || new Date(recibidaEn).toISOString() !== recibidaEn) return rechazo('FECHA_RECEPCION');
  if (typeof entrada?.message !== 'string') return rechazo('MENSAJE_DEBE_SER_TEXTO');
  if (entrada.message.charCodeAt(0) === 0xfeff || Buffer.byteLength(entrada.message, 'utf8') > 8192) return rechazo('CODIFICACION_O_TAMANO');
  if (entrada.retained === true || entrada.retain === true) return rechazo('RETAIN_NO_ADMITIDO');
